# generics provides ready-made API views; permissions controls access.
from rest_framework import generics, permissions

# The Request model is used to query the authenticated user's Requests.
from apps.requests.models import Request

# The serializer validates input and converts Request objects into API data.
from apps.requests.serializers import RequestSerializer

# Path extracts the originl filename without its extension.
from pathlib import Path

# ContentFile converts generated by bytes into a Django file.
from django.core.files.base import ContentFile

# The processing service transforms the input XLSX into to the analyzed output.
from apps.requests.services import process_publications_spreadsheet


# ListCreateAPIView handles GET for listing and POST for creation.
class RequestListCreateView(generics.ListCreateAPIView):

    # Use RequestSerializer for both input validation and response serialization.
    serializer_class = RequestSerializer

    # Require a valid authenticated user for both GET and POST.
    permission_classes = [permissions.IsAuthenticated]

    # ListCreateAPIView calls this method when handling a GET request.
    def get_queryset(self):

        # Return only Requests owned by the authenticated user.
        return Request.objects.filter(user=self.request.user)
    
    # ListCreateAPIView calls this hook after POST data is validated.
    def perform_create(self, serializer):

        # Read the validated file and criteria without trusting raw request data.
        input_file = serializer.validated_data["input_file"]
        criteria = serializer.validated_data["criteria"]

        # Process the spreadsheet synchronously before saving the Request.
        processed_file = process_publications_spreadsheet(
            input_file,
            criteria,
        )

        # Build the output filename from the original uploaded filename.
        input_name = Path(input_file.name)
        output_name = f"{input_name.stem} (análise robô).xlsx"

        # Copy the generated bytes into a Django-compatible file object.
        output_content = ContentFile(
            processed_file.getvalue(),
            name=output_name,
        )

        # Release the temporary in-memory output.
        processed_file.close()

        # openpyxl moved the input cursor while reading the workbook.
        # Return it to the beginning before Django stores the original file.
        input_file.seek(0)
        
        # Save the Request and both files only after processing succeeds.
        serializer.save(
            user=self.request.user,
            output_file=output_content,
        )